# -*- coding: utf-8 -*-
from odoo import models, fields, api

class HrExpenseSheet(models.Model):
    _name = 'hr.expense.sheet'
    _description = 'HR EXPENSE SHEET'
    _order = 'id desc'

    activity_ids = fields.One2many(comodel_name="mail.activity", inverse_name='parent_id', string="Activities")
    activity_state = fields.Selection(selection=[["overdue","Overdue"],["today","Today"],["planned","Planned"]], string="Activity State", readonly=True, help="Status based on activities\nOverdue: Due date is already passed\nToday: Activity date is today\nPlanned: Future activities.")
    activity_user_id = fields.Many2one(comodel_name="res.users", string="Responsible User")
    activity_type_id = fields.Many2one(comodel_name="mail.activity.type", string="Next Activity Type")
    activity_type_icon = fields.Char(string="Activity Type Icon", readonly=True, help="Font awesome icon e.g. fa-tasks")
    activity_date_deadline = fields.Date(string="Next Activity Deadline", readonly=True)
    my_activity_date_deadline = fields.Date(string="My Activity Deadline", readonly=True)
    activity_summary = fields.Char(string="Next Activity Summary")
    activity_exception_decoration = fields.Selection(selection=[["warning","Alert"],["danger","Error"]], string="Activity Exception Decoration", readonly=True, help="Type of the exception activity on record.")
    activity_exception_icon = fields.Char(string="Icon", readonly=True, help="Icon to indicate an exception activity.")
    activity_calendar_event_id = fields.Many2one(comodel_name="calendar.event", string="Next Activity Calendar Event", readonly=True)
    message_is_follower = fields.Boolean(string="Is Follower", readonly=True)
    message_follower_ids = fields.One2many(comodel_name="mail.followers", inverse_name='parent_id', string="Followers")
    message_partner_ids = fields.Many2many(comodel_name="res.partner", string="Followers (Partners)")
    message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Messages")
    has_message = fields.Boolean(string="Has Message", readonly=True)
    message_needaction = fields.Boolean(string="Action Needed", readonly=True, help="If checked, new messages require your attention.")
    message_needaction_counter = fields.Integer(string="Number of Actions", readonly=True, help="Number of messages requiring action")
    message_has_error = fields.Boolean(string="Message Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    message_has_error_counter = fields.Integer(string="Number of errors", readonly=True, help="Number of messages with delivery error")
    message_attachment_count = fields.Integer(string="Attachment Count", readonly=True)
    message_main_attachment_id = fields.Many2one(comodel_name="ir.attachment", string="Main Attachment", readonly=True)
    website_message_ids = fields.One2many(comodel_name="mail.message", inverse_name='parent_id', string="Website Messages", help="Website communication history")
    message_has_sms_error = fields.Boolean(string="SMS Delivery error", readonly=True, help="If checked, some messages have a delivery error.")
    name = fields.Char(string="Expense Report Summary", required=True)
    expense_line_ids = fields.One2many(comodel_name="hr.expense", inverse_name='parent_id', string="Expense Lines")
    product_ids = fields.Many2many(comodel_name="product.product", string="Categories", readonly=True)
    is_editable = fields.Boolean(string="Expense Lines Are Editable By Current User", readonly=True)
    expense_number = fields.Integer(string="Number of Expenses", readonly=True)
    state = fields.Selection(selection=[["draft","Draft"],["submit","Submitted"],["approve","Approved"],["post","Posted"],["done","Done"],["cancel","Refused"]], string="Status", required=True, readonly=True)
    payment_state = fields.Selection(selection=[["not_paid","Not Paid"],["in_payment","In Payment"],["paid","Paid"],["partial","Partially Paid"],["reversed","Reversed"],["invoicing_legacy","Invoicing App Legacy"]], string="Payment Status", readonly=True)
    employee_id = fields.Many2one(comodel_name="hr.employee", string="Employee", required=True, readonly=True)
    address_id = fields.Many2one(comodel_name="res.partner", string="Employee Home Address")
    payment_mode = fields.Selection(selection=[["own_account","Employee (to reimburse)"],["company_account","Company"],["3th","3th Party (Pay on Behalf)"]], string="Paid By", readonly=True)
    user_id = fields.Many2one(comodel_name="res.users", string="Manager", readonly=True)
    total_amount = fields.Monetary(string="Total Amount", readonly=True)
    untaxed_amount = fields.Monetary(string="Untaxed Amount", readonly=True)
    total_amount_taxes = fields.Monetary(string="Taxes", readonly=True)
    amount_residual = fields.Monetary(string="Amount Due", readonly=True)
    company_id = fields.Many2one(comodel_name="res.company", string="Company", required=True, readonly=True)
    currency_id = fields.Many2one(comodel_name="res.currency", string="Currency", readonly=True)
    attachment_number = fields.Integer(string="Number of Attachments", readonly=True)
    attachment_ids = fields.One2many(comodel_name="ir.attachment", inverse_name='parent_id', string="Attachments of expenses")
    journal_displayed_id = fields.Many2one(comodel_name="account.journal", string="Journal", readonly=True)
    journal_id = fields.Many2one(comodel_name="account.journal", string="Expense Journal", help="The journal used when the expense is done.")
    bank_journal_id = fields.Many2one(comodel_name="account.journal", string="Bank Journal", help="The payment method used when the expense is paid by the company.")
    accounting_date = fields.Date(string="Accounting Date", readonly=True)
    account_move_id = fields.Many2one(comodel_name="account.move", string="Journal Entry", readonly=True)
    department_id = fields.Many2one(comodel_name="hr.department", string="Department")
    is_multiple_currency = fields.Boolean(string="Handle lines with different currencies", readonly=True)
    can_reset = fields.Boolean(string="Can Reset", readonly=True)
    can_approve = fields.Boolean(string="Can Approve", readonly=True)
    approval_date = fields.Datetime(string="Approval Date", readonly=True)
    pay_type = fields.Selection(selection=[["reimburse","Direct Reimbursement"],["advance_clear","Advance Clearing"]], string="Payment Type", required=True)
    payment_ids = fields.Many2many(comodel_name="account.payment", string="Payment", readonly=True)
    has_invoice = fields.Boolean(string="Has Invoice", readonly=True)
    vendor_bill_journal_id = fields.Many2one(comodel_name="account.journal", string="Vendor Bill Journal", help="The journal used when the expense sheet has invoice.")
    invisible_payment = fields.Boolean(string="Invisible Payment", readonly=True, help="Technical field is used to show/hide button Payment")
    move_ids = fields.One2many(comodel_name="account.move", inverse_name='parent_id', string="Journal Entries", readonly=True)
    l10n_description = fields.Text(string="Description")
    is_advanced_payment = fields.Boolean(string="Use Advanced Payment")
    party_id = fields.Many2one(comodel_name="res.partner", string="Party", readonly=True)
    code = fields.Char(string="Expense Code", readonly=True)
    job_ids = fields.Many2many(comodel_name="freight.job", string="Jobs", readonly=True)
    house_ids = fields.Many2many(comodel_name="freight.shipment.house", string="House B/L", readonly=True)
    master_ids = fields.Many2many(comodel_name="freight.shipment.master", string="Master B/L", readonly=True)
    performance_date = fields.Date(string="Performance Date", readonly=True)
    job_count = fields.Integer(string="Job Count", readonly=True)
    payment_note_ids = fields.Many2many(comodel_name="freight.credit.note", string="Payment Management", readonly=True)
    payment_note_count = fields.Integer(string="Payment Management", readonly=True)
    employee_advance_ids = fields.Many2many(comodel_name="employee.advance", string="Employee Advances", readonly=True)
    employee_advance_count = fields.Integer(string="Employee Advance Count", readonly=True)
    advance_reconcile_ids = fields.Many2many(comodel_name="employee.advance.reconcile", string="Advance Reconciles", readonly=True)
    advance_reconcile_count = fields.Integer(string="Advance Reconcile Count", readonly=True)
    has_container_deposit = fields.Boolean(string="Has Container Deposit", readonly=True, help="Sheet có ít nhất một dòng chi phí loại \"Cược cont\".")
    cds_number = fields.Char(string="CDs Number", readonly=True)
    approved_by_id = fields.Many2one(comodel_name="res.users", string="Approved By", readonly=True)
    payment_date = fields.Date(string="Payment Date")
